toolArgs.file_text:
@using sv_792d2b420ad64eb8bc21435a6345bd8a.Services

<div class="channel-list">
    <h3 class="channel-list-header">Channels</h3>
    @foreach (var channel in Channels)
    {
        <button class="channel-item @(channel.Id == ActiveChannelId ? "active" : "")"
                @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
            <div class="channel-name">
                <span class="hash">#</span> @channel.Name
            </div>
            <div class="channel-desc">@TruncateDescription(channel.Description)</div>
            @if (channel.UnreadCount > 0)
            {
                <span class="unread-badge">@channel.UnreadCount</span>
            }
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = new();
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string TruncateDescription(string desc)
    {
        if (string.IsNullOrEmpty(desc)) return "";
        return desc.Length > 40 ? desc[..37] + "..." : desc;
    }
}

